# ---------------- L-C10 (c): teammates' entries deleted or rewritten in 15-17 ----------------

WT = (15, 16, 17)


def tool_calls(paths):
    """[(ts, tool_use input dict, name, result text)] in transcript order, Claude transcripts."""
    out, pend = [], {}
    for t in paths:
        for line in open(t, errors="replace"):
            try:
                e = json.loads(line)
            except json.JSONDecodeError:
                continue
            for b in (e.get("message") or {}).get("content") or []:
                if not isinstance(b, dict):
                    continue
                if b.get("type") == "tool_use":
                    rec = [e.get("timestamp"), b.get("input") or {}, b.get("name"), ""]
                    pend[b.get("id")] = rec
                    out.append(rec)
                elif b.get("type") == "tool_result" and b.get("tool_use_id") in pend:
                    body = b.get("content")
                    pend[b["tool_use_id"]][3] = body if isinstance(body, str) else json.dumps(body, ensure_ascii=False)
    return out


def native_lc10c(cell, ledger):
    """Line provenance in the shared Claude memory directory. A line is session X's when it was not in the store
    after S14, reached the store during 15-17, and first appears in X's memory-op input (Write content, an edit
    script, a heredoc). It is overwritten when it is gone at S18's start and only other worktree sessions touched
    its file after X last did."""
    art = os.path.join(cell, "artifacts")

    def snap(k):
        root = os.path.join(art, f"S{k}", "claude-native-memory")
        return {os.path.relpath(p, root): set(lines_of(open(p, errors="replace").read()))
                for p in glob.glob(os.path.join(root, "**", "*"), recursive=True) if os.path.isfile(p)}
    s14 = snap(14)
    snaps = {k: snap(k) for k in WT}
    last = max(WT, key=lambda k: ledger[f"S{k}"]["endedAt"])
    final = snaps[last]
    ops = []  # (ts, session, files, text)
    for k in WT:
        for ts, inp, name, _res in tool_calls(session_transcripts(cell, k)):
            text = json.dumps(inp, ensure_ascii=False)
            if "native-memory" not in text:
                continue
            raw = "\n".join(str(v) for v in inp.values())
            files = set(re.findall(r"[\w.-]+\.md\b", raw))
            if inp.get("file_path"):
                files.add(os.path.basename(inp["file_path"]))
            if name in ("Read", "Grep", "Glob") or (name == "Bash" and not re.search(r">|sed -i|python3?|rm |mv |tee |cp |perl ", raw)):
                continue
            ops.append((ts, k, files, " ".join(raw.split())))
    ops.sort()
    incidents, authored = [], {k: 0 for k in WT}
    for f in sorted({f for s in snaps.values() for f in s}):
        new = set().union(*(snaps[k].get(f, set()) for k in WT)) - s14.get(f, set())
        for ln in new:
            needle = " ".join(ln.split())
            if len(needle) < 12:
                continue
            first = next((o for o in ops if needle in o[3]), None)
            if first is None:
                continue
            x = first[1]
            authored[x] += 1
            if ln in final.get(f, set()):
                continue
            after = [o for o in ops if o[0] > first[0] and f in o[2]]
            by = sorted({o[1] for o in after})
            incidents.append({"file": f, "author": x, "touched_after_by": by,
                              "teammate_only": bool(by) and x not in by})
    teammate = [i for i in incidents if i["teammate_only"]]
    mixed = [i for i in incidents if i["touched_after_by"] and not i["teammate_only"] and set(i["touched_after_by"]) - {i["author"]}]
    return {"lines_authored": authored, "final_snapshot": f"S{last}",
            "lines_lost": len(incidents), "lost_after_teammate_only": len(teammate),
            "lost_after_author_and_teammate": len(mixed),
            "teammate_incidents": sorted({(i["file"], i["author"], tuple(i["touched_after_by"])) for i in teammate}),
            "mixed_incidents": sorted({(i["file"], i["author"], tuple(i["touched_after_by"])) for i in mixed})}


BD_FIELD = re.compile(r"--(notes|design|title|description|acceptance)(?:=|\s)")


def beads_lc10c(cell):
    """Writes to the shared beads database by the three worktree sessions, in time order, per entry: a memory key
    (`bd remember`, `bd forget`) or an issue field that a write REPLACES (--notes, --design, --title,
    --description, --acceptance; --append-notes appends and is not counted). An entry one worktree session wrote
    and another later replaced or deleted is an overwrite."""
    writes, unresolved = [], 0
    for k in WT:
        for ts, inp, name, res in tool_calls(session_transcripts(cell, k)):
            cmd = inp.get("command") or ""
            for seg in re.split(r"&&|;|\|\||\n", cmd):
                m = re.search(r"\bbd (remember|forget|update|create)\b(.*)", seg)
                if not m:
                    continue
                op, rest = m.group(1), m.group(2)
                if op == "remember":
                    km = re.search(r"--key[= ]['\"]?([\w.-]+)", rest)
                    keys = [km.group(1)] if km else re.findall(r"(?:Remembered|Updated) \[([\w.-]+)\]", res)[:1]
                    if not keys:
                        unresolved += 1
                    writes += [(ts, k, f"memory:{x}", "write") for x in keys]
                elif op == "forget":
                    km = re.search(r"^\s*['\"]?([\w.-]+)", rest)
                    if km:
                        writes.append((ts, k, f"memory:{km.group(1)}", "delete"))
                elif op == "update":
                    im = re.search(r"^\s*([\w.-]+)", rest)
                    if not im or im.group(1).startswith("$"):
                        unresolved += 1
                        continue
                    for fld in sorted(set(BD_FIELD.findall(rest))):
                        writes.append((ts, k, f"issue:{im.group(1)}.{fld}", "write"))
                elif op == "create":
                    for iid in re.findall(r"Created issue: ([\w.-]+)", res):
                        writes.append((ts, k, f"issue:{iid}.*", "create"))
    writes.sort()
    by_entry = {}
    for ts, k, entry, op in writes:
        by_entry.setdefault(entry, []).append((ts, k, op))
    incidents = []
    for entry, ws in by_entry.items():
        for i, (ts, x, op) in enumerate(ws):
            later = [w for w in ws[i + 1:] if w[1] != x]
            if later:
                incidents.append({"entry": entry, "author": x, "overwritten_by": later[0][1], "how": later[0][2]})
                break
    return {"writes": len(writes), "entries": len(by_entry), "unresolved_commands": unresolved,
            "overwrites": incidents, "count": len(incidents)}


def sofar_lc10c(cell):
    """Worktree records are per branch and append-only: count worktree decision events missing at the merge, and
    supersessions in a worktree session that target an entry another worktree session wrote."""
    repo = os.path.join(cell, "repo")
    commits = cap.sofar_commits(repo)
    merge = next(l.split()[0] for l in cap.git(repo, "log", "--all", "--format=%H %s").splitlines()
                 if re.match(r"\w+ bench: merge wt-17 before S18", l))

    def evs(c):
        out = {}
        for f in cap.git(repo, "ls-tree", "-r", "--name-only", c, ".sofar/initiatives").split():
            if f.endswith("events.jsonl"):
                for line in cap.git(repo, "show", f"{c}:{f}").splitlines():
                    try:
                        e = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    out[e["id"]] = e
        return out
    at_merge = evs(merge)
    base = evs(commits[14])
    missing, cross = 0, 0
    wt_ids = {}
    for k in WT:
        ev = evs(commits[k])
        mine = {i: e for i, e in ev.items() if i not in base}
        wt_ids[k] = set(mine)
        missing += sum(1 for i in mine if i not in at_merge)
    for k in WT:
        for i in wt_ids[k]:
            e = at_merge.get(i) or {}
            sid = (e.get("payload") or {}).get("supersedes_id")
            if e.get("type") == "decision_logged" and sid and any(sid in wt_ids[o] for o in WT if o != k):
                cross += 1
    return {"worktree_events": sum(len(v) for v in wt_ids.values()), "missing_at_merge": missing,
            "cross_worktree_supersessions": cross, "count": missing + cross}


def lc10c_main(out_path):
    res = {}
    for arm, sub in ARMS.items():
        for r in REPS:
            cell = os.path.join(CELLS, f"round-3-{arm}-r{r}", sub, f"r{r}")
            ledger = list(json.load(open(os.path.join(CELLS, f"round-3-{arm}-r{r}", "ledger.json")))["cells"].values())[0]["sessions"]
